 LinearLayout content,nav,filters,modes;HorizontalScrollView filterScroll;ScrollView scroll;DevicePage devicePage;String actionView="tasks",filter="全部",device="overview";String lastRender="";java.util.HashSet<String> expanded=new java.util.HashSet<>();
