 TextView chip(LinearLayout row,String label,boolean selected,Runnable action){TextView t=control(row,label,selected,action);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-2,-2);lp.setMargins(0,0,dp(4),0);t.setLayoutParams(lp);return t;}
 void badge(LinearLayout parent,String icon,int tint,int size){ImageView view=new ImageView(this);view.setImageDrawable(HyperStyle.icon(this,icon,tint));int padding=dp(size>=36?9:7);view.setPadding(padding,padding,padding,padding);int wash=(tint&0x00ffffff)|(HyperStyle.dark(this)?0x30000000:0x16000000);view.setBackground(HyperStyle.shape(this,wash,12));view.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);parent.addView(view,new LinearLayout.LayoutParams(dp(size),dp(size)));}
 void divider(LinearLayout parent,int inset){View line=new View(this);line.setBackgroundColor(HyperStyle.soft(this));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(1));p.setMargins(dp(inset),0,0,0);parent.addView(line,p);}
