 void empty(LinearLayout parent,String icon,String heading,String description,Runnable retry){LinearLayout card=DeviceCards.panel(this,parent);card.setGravity(Gravity.CENTER);card.setPadding(dp(24),dp(36),dp(24),dp(36));badge(card,icon,HyperStyle.accent(this),48);TextView label=text(heading,19,HyperStyle.ink(this));label.setPadding(0,dp(18),0,dp(8));label.setGravity(Gravity.CENTER);card.addView(label);if(!description.isEmpty()){TextView detail=text(description,15,HyperStyle.muted(this));detail.setGravity(Gravity.CENTER);card.addView(detail);}if(retry!=null){TextView button=text("重新获取",16,HyperStyle.accent(this));button.setPadding(dp(20),dp(16),dp(20),dp(12));button.setOnClickListener(v->retry.run());card.addView(button);}}
 boolean hasInnerBack(){return tab.equals("settings")||(tab.equals("news")&&NewsStore.selected!=null)||(tab.equals("devices")&&!device.equals("overview"))||(tab.equals("actions")&&actionView.equals("calendar"));}
 void goBack(){if(tab.equals("news")&&NewsStore.selected!=null){NewsStore.back(this);return;}if(tab.equals("settings"))tab=previousTab;else if(tab.equals("devices"))device="overview";else if(tab.equals("actions"))actionView="tasks";lastRender="";render();HyperStyle.enter(content);}
 @Override public void onBackPressed(){if(hasInnerBack())goBack();else super.onBackPressed();}
 void settings(){
  LinearLayout connection=DeviceCards.panel(this,content);connection.addView(text("数据与连接",20,HyperStyle.ink(this)));connectionState=text("",15,HyperStyle.accent(this));receivedState=text("",14,HyperStyle.muted(this));connection.addView(connectionState);connection.addView(receivedState);updateConnection();if(Store.read(this,"news")!=null)setting(connection,"本期信息范围",()->NewsStore.coverage(this));
  LinearLayout card=DeviceCards.panel(this,content);card.addView(text("连接与桌面",20,0xff19212e));
  setting(card,"导入连接文件",this::choose);setting(card,"添加桌面小组件",this::chooseWidget);
  card.addView(text("应用运行时自动更新桌面小组件；从最近任务划掉后停止。",13,0xff77818f));
  LinearLayout app=DeviceCards.panel(this,content);app.addView(text("CXY 工作台",20,0xff19212e));setting(app,"检查应用更新",()->AppUpdater.check(this));TextView update=text("",13,0xff657184);update.setId(AppUpdater.STATUS_ID);app.addView(update);
  try{app.addView(text("Android "+getPackageManager().getPackageInfo(getPackageName(),0).versionName,13,0xff77818f));}catch(Exception e){}
 }
 void iconButton(LinearLayout row,String icon,String description,Runnable action){ImageView v=new ImageView(this);v.setImageDrawable(HyperStyle.icon(this,icon,HyperStyle.ink(this)));v.setContentDescription(description);v.setPadding(dp(11),dp(11),dp(11),dp(11));v.setBackground(HyperStyle.press(this,Color.TRANSPARENT,24));HyperStyle.pressMotion(v);v.setOnClickListener(w->{if(icon.equals("refresh")&&HyperStyle.motion())v.animate().rotationBy(360).setDuration(450).start();action.run();});row.addView(v,new LinearLayout.LayoutParams(dp(46),dp(46)));}
 void navigation(String id,String label){boolean selected=id.equals(tab);LinearLayout item=column();item.setGravity(Gravity.CENTER);item.setPadding(dp(8),dp(8),dp(8),dp(8));ImageView icon=new ImageView(this);icon.setImageDrawable(HyperStyle.icon(this,id,selected?HyperStyle.accent(this):HyperStyle.muted(this)));item.addView(icon,new LinearLayout.LayoutParams(dp(24),dp(24)));TextView caption=text(label,12,selected?HyperStyle.accent(this):HyperStyle.muted(this));caption.setGravity(Gravity.CENTER);caption.setTypeface(null,selected?android.graphics.Typeface.BOLD:android.graphics.Typeface.NORMAL);item.addView(caption);item.setContentDescription(label);item.setBackground(HyperStyle.press(this,selected?HyperStyle.wash(this):Color.TRANSPARENT,22));HyperStyle.pressMotion(item);item.setOnClickListener(v->{tab=id;lastRender="";scroll.scrollTo(0,0);render();HyperStyle.enter(content);if("news".equals(tab))NewsStore.refresh(this,()->runOnUiThread(this::render));});nav.addView(item,new LinearLayout.LayoutParams(0,-2,1));}
 void setting(LinearLayout card,String name,Runnable action){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setMinimumHeight(dp(64));row.setBackground(HyperStyle.press(this,Color.TRANSPARENT,12));String icon=name.startsWith("↗")?"link":name.contains("导入")?"import":name.contains("组件")?"widgets":"refresh";ImageView image=new ImageView(this);image.setImageDrawable(HyperStyle.icon(this,icon,HyperStyle.accent(this)));image.setPadding(dp(8),dp(8),dp(8),dp(8));image.setBackground(HyperStyle.shape(this,HyperStyle.wash(this),12));row.addView(image,new LinearLayout.LayoutParams(dp(36),dp(36)));TextView label=text(name,16,HyperStyle.ink(this));label.setPadding(dp(14),dp(12),0,dp(12));row.addView(label,new LinearLayout.LayoutParams(0,-2,1));row.addView(text("›",24,HyperStyle.muted(this)));HyperStyle.pressMotion(row);row.setOnClickListener(v->action.run());card.addView(row);}
 void chooseWidget(){String[] labels={"行动台","设备总览","Mac","WinPC","Linux","手机","家庭网关"};Class<?>[] classes={ActionWidget.class,DeviceWidget.class,MacWidget.class,WinPCWidget.class,LinuxWidget.class,PhoneWidget.class,GatewayWidget.class};android.appwidget.AppWidgetManager manager=android.appwidget.AppWidgetManager.getInstance(this);if(!manager.isRequestPinAppWidgetSupported()){Toast.makeText(this,"请在桌面长按空白处，从小组件中添加CXY工作台",Toast.LENGTH_LONG).show();return;}HyperStyle.dialog(new AlertDialog.Builder(HyperStyle.dialogContext(this)).setTitle("添加桌面小组件").setItems(labels,(dialog,which)->{if(!manager.requestPinAppWidget(new ComponentName(this,classes[which]),null,null))Toast.makeText(this,"桌面未接受添加请求，请从桌面小组件列表添加",Toast.LENGTH_LONG).show();}).create());}
 void selectActionIntent(Intent i){if(i.hasExtra("actionGroup")){String[] f={"优先做","正在做","当前可做","条件做","全部"};filter=f[Math.max(0,Math.min(4,i.getIntExtra("actionGroup",0)))];}}
 void selectDeviceIntent(Intent i){if(i.hasExtra("device"))device=i.getStringExtra("device");}
 void choose(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,11);}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==11&&result==RESULT_OK&&data!=null&&data.getData()!=null){try{Store.importConfig(this,data.getData());startLive();Toast.makeText(this,"连接已导入",Toast.LENGTH_SHORT).show();Store.refresh(this,true,()->runOnUiThread(this::render));}catch(Exception e){HyperStyle.dialog(new AlertDialog.Builder(HyperStyle.dialogContext(this)).setTitle("未导入").setMessage(e.getMessage()).setPositiveButton("确定",null).create());}}}
 void startLive(){if(!Store.configured(this)||LiveService.running)return;try{startForegroundService(new Intent(this,LiveService.class));}catch(RuntimeException e){Toast.makeText(this,"桌面实时更新未能启动："+e.getClass().getSimpleName(),Toast.LENGTH_LONG).show();}}
 void updateConnection(){if(connectionState==null)return;String error=Store.err(this);connectionState.setText(!Store.configured(this)?"尚未连接":error.isEmpty()?"已连接":error);connectionState.setTextColor(error.isEmpty()?HyperStyle.accent(this):0xffa45e37);long at=Store.prefs(this).getLong("lastFetch",0);receivedState.setText("最近接收  "+Store.stamp(at));receivedState.setVisibility(at>0?View.VISIBLE:View.GONE);}
 @Override protected void onResume(){super.onResume();resumed=true;Store.pageActive=true;startLive();handler.removeCallbacks(tick);handler.post(tick);if("news".equals(tab))NewsStore.refresh(this,()->runOnUiThread(this::render));}
 @Override protected void onPause(){resumed=false;Store.pageActive=false;handler.removeCallbacks(tick);super.onPause();}
 @Override protected void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);if(i.hasExtra("tab"))tab=i.getStringExtra("tab");selectDeviceIntent(i);selectActionIntent(i);render();}
 void render(){if(content==null)return;
  if(tab.equals("settings"))updateConnection();
  String error=Store.err(this);boolean connectionMissing=!Store.configured(this);boolean showError=(connectionMissing||!error.isEmpty())&&!tab.equals("settings");boolean edition=tab.equals("news")&&NewsStore.selected==null&&!showError;status.setText(showError?(connectionMissing?"尚未连接 · 在设置中导入连接文件":error):edition?NewsStore.header(this):"");status.setVisibility(showError||(edition&&!status.getText().toString().isEmpty())?View.VISIBLE:View.GONE);
  updateHeading();
  if(tab.equals("devices")&&devicePage!=null&&devicePage.getParent()==content){devicePage.select(device);devicePage.update(Store.read(this,"telemetry"));return;}
  String key=tab+filter+device+actionView+CalendarPage.version()+("devices".equals(tab)?"devices":"news".equals(tab)?NewsStore.version(this):"settings".equals(tab)?"settings":String.valueOf(Store.read(this,"actions")));
  if(key.equals(lastRender))return;lastRender=key;
  nav.removeAllViews();
  String[] ids={"actions","devices","news"},labels={"行动","设备","每日信息"};for(int n=0;n<3;n++){final String id=ids[n];navigation(id,labels[n]);}
  filters.removeAllViews();content.removeAllViews();devicePage=null;filterScroll.setVisibility(View.GONE);modes.removeAllViews();modes.setVisibility(tab.equals("actions")?View.VISIBLE:View.GONE);if(tab.equals("actions")){control(modes,"事项",actionView.equals("tasks"),()->{actionView="tasks";lastRender="";scroll.scrollTo(0,0);render();});control(modes,"日程",actionView.equals("calendar"),()->{actionView="calendar";lastRender="";scroll.scrollTo(0,0);render();});}
  if("settings".equals(tab)){settings();return;}
  if("news".equals(tab)){NewsStore.render(this,content);filterScroll.setVisibility(filters.getChildCount()>0?View.VISIBLE:View.GONE);return;}
  if("devices".equals(tab)){devicePage=new DevicePage(this);content.addView(devicePage,new LinearLayout.LayoutParams(-1,-2));devicePage.update(Store.read(this,"telemetry"));devicePage.select(device);return;}
  if(actionView.equals("calendar")){CalendarPage.render(this,content);return;}
  ActionPage.render(this,content);filterScroll.setVisibility(View.VISIBLE);
 }
 void updateHeading(){boolean calendar=tab.equals("actions")&&actionView.equals("calendar");title.setText("devices".equals(tab)?"设备看板":"news".equals(tab)?"每日信息":"settings".equals(tab)?"设置":calendar?"日程":"行动");boolean back=hasInnerBack();pageIcon.setImageDrawable(HyperStyle.icon(this,back?"back":calendar?"calendar":tab,HyperStyle.accent(this)));pageIcon.setContentDescription(back?"返回":null);pageIcon.setClickable(back);pageIcon.setImportantForAccessibility(back?View.IMPORTANT_FOR_ACCESSIBILITY_YES:View.IMPORTANT_FOR_ACCESSIBILITY_NO);}
